      "reason": "The title explicitly identifies the work as a \"systematic review\" (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "\"How does the SARS-CoV-2 reinfection rate change over time?\"",
      "reason": "The title states the main review question/objective: the change in SARS-CoV-2 reinfection rate over time (population/exposure: SARS-CoV-2 reinfection)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "\"The global evidence from systematic review and meta-analysis\"",
